rss.channel:
    {{ site_name }}
    {{ site_url }}/
    {{ site_description }}
    en
    {%- if build_date %}
    {{ build_date }}
    {%- endif %}

{%- for a in articles %}


      {{ a.title }}
      {{ site_url }}{{ a.url }}
      {{ site_url }}{{ a.url }}
      {{ a.published_at|rfc822 }}
      {%- if a.author %}
      noreply@{{ site_url.split('://')[-1] }} ({{ a.author.name }})
      {%- endif %}
      {%- if a.category %}
      {{ a.category.name }}
      {%- endif %}
      {{ a.description }}

{%- endfor %}
